function parseCSV(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '
' || c === '') {
      if (c === '' && text[i + 1] === '
') i++;
      row.push(field); field = '';
      if (row.some(v => v !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some(v => v !== '')) rows.push(row);
  const header = rows.shift().map(h => h.trim());
  return rows.map(r => Object.fromEntries(header.map((h, i) => [h, (r[i] || '').trim()])));
}

const project = {
  name: 'AI Adoption Project — ABCDE Ltd.',
  description: FILES.description.trim(),
  timeline: parseCSV(FILES.timeline).map(p => ({ ...p, phase: Number(p.phase), start_week: Number(p.start_week), end_week: Number(p.end_week) })),
  risks: parseCSV(FILES.risks),
  tasks: parseCSV(FILES.tasks),
};

return [{ json: { ...$input.first().json, project } }];

// Compute Facts — deterministic project analytics. Counting, filtering and date maths happen HERE, in code,
// so the LLM agents only format and explain numbers; they never have to calculate them (anti-hallucination design).
const t0 = Date.now();
const { config: cfg, project: p } = $input.first().json;
const DAY = 86400000;
const toDate = s => new Date(s + 'T00:00:00Z');
const fmt = d => d.toISOString().slice(0, 10);
const asOf = toDate(cfg.as_of_date);
const start = toDate(cfg.project_start);
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];
const sprintNo = s => Number(String(s).replace(/\D/g, '')) || 0;

const tasks = p.tasks.map(t => ({
  id: t.task_id, name: t.task_name, status: t.status, assignee: t.assignee, priority: t.priority,
  sprint: t.sprint, due: t.due_date, label: t.labels, description: t.description,
  days_to_due: Math.round((toDate(t.due_date) - asOf) / DAY),
}));
const compact = t => ({ id: t.id, name: t.name, status: t.status, assignee: t.assignee, priority: t.priority, sprint: t.sprint, due: t.due, days_to_due: t.days_to_due });
const counts = arr => Object.fromEntries([...STATUSES.map(s => [s, arr.filter(t => t.status === s).length]), ['Total', arr.length]]);

// Status counts, whole project and per sprint
const status_counts = counts(tasks);
const sprints = [...new Set(tasks.map(t => t.sprint))].sort((a, b) => sprintNo(a) - sprintNo(b));
const by_sprint = Object.fromEntries(sprints.map(s => {
  const ts = tasks.filter(t => t.sprint === s);
  return [s, { counts: counts(ts), tasks: ts.map(compact) }];
}));

// Delivery signals
const blocked = tasks.filter(t => t.status === 'Blocked').map(t => ({ ...compact(t), reason: `Blocked: ${(t.description.split('BLOCKED:')[1] || t.description).trim()}` }));
const overdue = tasks.filter(t => t.status !== 'Done' && t.days_to_due < 0)
  .map(t => ({ ...compact(t), reason: `Overdue by ${-t.days_to_due} day(s), still ${t.status}` }));
const at_risk = tasks.filter(t => t.days_to_due >= 0 && (
  (t.status === 'In Progress' && t.days_to_due <= cfg.at_risk_days_in_progress) ||
  (t.status === 'To Do' && t.days_to_due <= cfg.at_risk_days_todo)))
  .map(t => ({ ...compact(t), reason: `Due in ${t.days_to_due} day(s), still ${t.status}` }));
const at_risk_rules = `Blocked = status Blocked; Overdue = not Done and due date before ${cfg.as_of_date}; At risk = In Progress and due within ${cfg.at_risk_days_in_progress} days, or To Do and due within ${cfg.at_risk_days_todo} days.`;

// Timeline -> dated phases and milestones (week 1 starts on project_start)
const phases = p.timeline.map(ph => {
  const s = new Date(start.getTime() + (ph.start_week - 1) * 7 * DAY);
  const e = new Date(start.getTime() + (ph.end_week * 7 - 1) * DAY);
  const schedule_status = e < asOf ? 'Past (scheduled end date passed)' : (s <= asOf ? 'Current' : 'Upcoming');
  return {
    phase: ph.phase, name: ph.phase_name, weeks: `${ph.start_week}-${ph.end_week}`, start_date: fmt(s), end_date: fmt(e),
    schedule_status, key_activities: ph.key_activities, milestones: ph.milestones_deliverables.split(';').map(m => m.trim()).filter(Boolean),
  };
});
const milestones = phases.flatMap(ph => ph.milestones.map(m => ({
  milestone: m, phase: `${ph.phase}. ${ph.name}`, due: ph.end_date, days_to_due: Math.round((toDate(ph.end_date) - asOf) / DAY),
})));
const upcoming_milestones = milestones.filter(m => m.days_to_due >= 0 && m.days_to_due <= cfg.milestone_window_days);
const next_after_window = milestones.filter(m => m.days_to_due > cfg.milestone_window_days).slice(0, 3);
const current_phase = phases.find(ph => ph.schedule_status === 'Current') || null;
const project_end = phases.length ? phases[phases.length - 1].end_date : null;

// Current sprint = sprint of the earliest open, non-overdue task
const open = tasks.filter(t => t.status !== 'Done' && t.days_to_due >= 0).sort((a, b) => a.days_to_due - b.days_to_due);
const current_sprint = open.length ? open[0].sprint : null;

// Rule-based health (documented so the LLM never "decides" it)
const health_reasons = [];
blocked.forEach(t => health_reasons.push(`${t.id} ${t.name} is Blocked (${t.priority} priority)`));
overdue.forEach(t => health_reasons.push(`${t.id} ${t.name} is overdue (due ${t.due})`));
if (at_risk.length) health_reasons.push(`${at_risk.length} task(s) at risk of missing due dates in the next ${cfg.at_risk_days_todo} days`);
const issues = blocked.length + overdue.length;
const health = issues >= 3 ? 'RED' : issues >= 1 ? 'AMBER' : 'GREEN';

// Data-quality notes surfaced to agents instead of silently "fixed"
const data_notes = [];
const lastDue = tasks.map(t => t.due).sort().pop();
if (project_end && lastDue < project_end) data_notes.push(`Task board ends ${lastDue}; timeline runs to ${project_end} (week 24). Board and timeline are not fully aligned.`);

const facts = {
  report_date: cfg.as_of_date,
  project_start: cfg.project_start,
  project_end,
  status_counts,
  percent_done: Math.round((status_counts.Done / status_counts.Total) * 100),
  current_sprint,
  current_phase,
  by_sprint,
  blocked, overdue, at_risk, at_risk_rules,
  phases, milestones, upcoming_milestones, next_after_window,
  health, health_reasons,
  data_notes,
  all_task_ids: tasks.map(t => t.id),
  all_risk_ids: p.risks.map(r => r.risk_id),
};

return [{ json: { ...$input.first().json, facts, facts_ms: Date.now() - t0 } }];

// Parse Route — reads the Orchestrator's JSON and applies deterministic guardrails on top of it.
const ctx = $('Build Router Request').first().json;
const resp = $input.first().json;
const raw = resp.choices?.[0]?.message?.content || '{}';
let r;
try { r = JSON.parse(raw); } catch (e) { r = { intent: 'unsupported', project_ref: 'none', sufficient: false, missing_info: ['Router returned invalid JSON'], reason: 'parse error' }; }

const INTENTS = ['plan', 'risk', 'status', 'milestone', 'stakeholder_update', 'unsupported'];
const intent = INTENTS.includes(r.intent) ? r.intent : 'unsupported';
const msg = ctx.message || '';
const sprintMatch = msg.match(/sprint\s*(\d+)/i);
const sprint = Number.isInteger(r.sprint) ? r.sprint : (sprintMatch ? Number(sprintMatch[1]) : null);
let project_ref = ['abcde', 'other', 'none'].includes(r.project_ref) ? r.project_ref : 'none';

// Guardrails (code wins over the model):
// 1. Empty message => clarify.  2. Data-dependent intents need loaded data.  3. "other" projects must be sufficient.
let route = intent;
const guardrails = [];
if (!msg) { route = 'clarify'; guardrails.push('empty request'); }
else if (intent === 'unsupported') { route = 'clarify'; guardrails.push('unsupported intent'); }
else if (project_ref !== 'abcde') {
  if (['status', 'milestone', 'stakeholder_update'].includes(intent)) {
    route = 'clarify'; guardrails.push('no task data supplied for a non-loaded project');
  } else if (r.sufficient !== true) {
    route = 'clarify'; guardrails.push('insufficient project detail');
  }
}
if (route === 'stakeholder_update' && sprint && !ctx.facts.by_sprint[`Sprint ${sprint}`]) {
  route = 'clarify'; guardrails.push(`Sprint ${sprint} not found on the task board`);
}

const usage = resp.usage || {};
const router = {
  intent, route, project_ref, sprint, audience: r.audience || null,
  user_supplied_details: r.user_supplied_details || '', sufficient: r.sufficient === true,
  missing_info: Array.isArray(r.missing_info) ? r.missing_info : [], reason: r.reason || '', guardrails,
};
const call = {
  agent: 'Orchestrator', model: resp.model || ctx.config.router_model,
  input_tokens: usage.prompt_tokens || 0, output_tokens: usage.completion_tokens || 0,
  latency_ms: Date.now() - ctx.router_started_ms, input: ctx.request.messages, output: raw,
  start_time: new Date(ctx.router_started_ms).toISOString(), end_time: new Date().toISOString(),
};
const { request, ...rest } = ctx;
return [{ json: { ...rest, router, calls: [call] } }];

// Package Response — collects the specialist's output (whichever branch ran) with usage and latency.
const CONTEXT_NODES = ['Planner Context', 'Risk Context', 'Status Context', 'Milestone Context', 'Stakeholder Context', 'Clarifier (rule-based)'];
const ran = CONTEXT_NODES.find(n => { try { return $(n).isExecuted; } catch (e) { return false; } });
const ctx = $(ran).first().json;
const calls = [...(ctx.calls || [])];
let answer;
if (ran === 'Clarifier (rule-based)') {
  answer = ctx.rule_based_answer;
  calls.push({ agent: ctx.agent_name, model: 'none (rule-based)', input_tokens: 0, output_tokens: 0, latency_ms: Date.now() - ctx.agent_started_ms, input: ctx.message, output: answer, start_time: new Date(ctx.agent_started_ms).toISOString(), end_time: new Date().toISOString() });
} else {
  const resp = $input.first().json;
  answer = resp.choices?.[0]?.message?.content || '(no content returned)';
  const u = resp.usage || {};
  calls.push({ agent: ctx.agent_name, model: resp.model || ctx.request.model, input_tokens: u.prompt_tokens || 0, output_tokens: u.completion_tokens || 0, latency_ms: Date.now() - ctx.agent_started_ms, input: ctx.request.messages, output: answer, start_time: new Date(ctx.agent_started_ms).toISOString(), end_time: new Date().toISOString() });
}
const { request, rule_based_answer, ...rest } = ctx;
return [{ json: { ...rest, answer, calls } }];

// Planner Context — selects only what the Planner needs (context minimisation = lower cost, less room to drift).
const ctx = $input.first().json;
const { facts, project, router } = ctx;
const SYSTEM = "ROLE: You are Mira's Planner Agent, a senior TPM who turns a project description and phase timeline into a structured, decision-ready project plan.

INPUT: A SOURCE DATA block containing (a) the project description, (b) the phase timeline with dates already computed by code, and (c) a compact task list from the Kanban board. Treat SOURCE DATA as the only truth.

OUTPUT: Markdown with EXACTLY these sections, in this order:
## 1. Project Summary
2-3 sentences using only facts from the description.
## 2. Goals & Success Metrics
Only goals stated in the description. If a goal has no numeric target, write "target not specified in source".
## 3. Phase Plan
Table: Phase | Weeks | Dates | Key Activities | Milestones / Deliverables | Linked Tasks (IDs from the task list)
Use the phases, weeks, dates and milestones exactly as given. A task may be linked only if its name clearly matches the phase activities.
## 4. Key Milestones
Bulleted list: milestone - due date (phase end date from SOURCE DATA).
## 5. Team & Governance
Only what the data says (the cross-functional task force; task-board assignees and their task areas).
## 6. Dependencies & Assumptions
Each line must be tagged [FROM DATA] or [ASSUMPTION].
## 7. Open Questions for the Sponsor
Things a real plan needs that the source does not specify (e.g. budget, tooling decisions, approval gates).

RULES:
1. Do NOT invent goals, KPIs, phases, milestones, dates, people, budgets or technologies.
2. Every milestone must appear in the timeline. Every date must be copied from SOURCE DATA - never calculate new dates.
3. Any inference must be tagged [ASSUMPTION].
4. If something is not in the data, write "Not specified in source data".
5. If the task board and the timeline disagree (e.g. a task due outside its phase window), note it under Dependencies & Assumptions rather than silently fixing it.

VAGUE INPUT RULE: If SOURCE DATA lacks a goal/scope, a timeline, or a team, do not produce a plan. Reply only: "INSUFFICIENT DETAIL - cannot generate a plan without: <missing items>".
";
let source;
if (router.project_ref === 'abcde') {
  source = {
    project: project.name,
    description: project.description,
    timeline_with_dates: facts.phases.map(({ phase, name, weeks, start_date, end_date, key_activities, milestones }) => ({ phase, name, weeks, start_date, end_date, key_activities, milestones })),
    task_list: Object.values(facts.by_sprint).flatMap(s => s.tasks).map(t => ({ id: t.id, name: t.name, status: t.status, assignee: t.assignee, sprint: t.sprint, due: t.due })),
    data_notes: facts.data_notes,
  };
} else {
  source = { project: 'User-described project', description: router.user_supplied_details, timeline_with_dates: 'Not provided', task_list: 'Not provided' };
}
const request = {
  model: ctx.config.specialist_model, temperature: 0.2,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `USER REQUEST: ${ctx.message}

SOURCE DATA:
${JSON.stringify(source, null, 1)}` },
  ],
};
return [{ json: { ...ctx, agent_name: 'Planner Agent', request, agent_started_ms: Date.now() } }];

// Risk Context — risk register + DETERMINISTIC evidence links between task-board signals and register risks.
// v2 (after baseline run 1): the LLM previously linked the blocked security review (T024) to R02 Integration and
// cited vague "ongoing tasks" with no ID. Links and the evidence-based ranking are now computed here, in code;
// the agent may only use these links.
const ctx = $input.first().json;
const { facts, project, router } = ctx;
const SYSTEM = "ROLE: You are Mira's Risk Assessor Agent. You produce project-specific risk assessments grounded in the project's risk register and live delivery signals.\n\nINPUT: A SOURCE DATA block with (a) the risk register R01-R10 (category, risk, impact, mitigation), (b) the project description, (c) evidence_links computed by code: for every risk, its evidence_strength (LIVE SIGNAL / PLANNED WORK ONLY / NO CURRENT SIGNAL), the live signals (task ID + Blocked / Overdue / At risk + reason) and planned related tasks, (d) evidence_ranking computed by code, and (e) the user's request.\n\nOUTPUT:\n- If the user asks a specific question (e.g. \"top 3 risks\"), answer ONLY that question, as a numbered list taken in order from evidence_ranking. For each risk give: Risk ID, category, the risk, why it ranks here (quote its live_signals), and the mitigation from the register. Do not add a full matrix.\n- If the user asks for a risk assessment, return Markdown with:\n  ## Risk Matrix\n  Table: ID | Category | Risk | Impact | Likelihood (H/M/L) | Severity (H/M/L) | Evidence in Project Data | Mitigation (register) | Next Action [SUGGESTED]\n  All ten register risks, ordered by evidence_ranking.\n  ## Live Signals Driving the Ratings\n  Bullet each live signal (task ID, status, due/reason) and the risk ID it is linked to in evidence_links.\n  ## Rating Method\n  One short paragraph: the register has no likelihood/severity scores, so ratings follow evidence_strength (LIVE SIGNAL = Likelihood H; PLANNED WORK ONLY = M; NO CURRENT SIGNAL = L) and the ranking rule in SOURCE DATA.\n\nRULES:\n1. Use ONLY risks R01-R10 from the register. Never add generic risks.\n2. Evidence for a risk may ONLY be the live_signals / planned_related_tasks listed for that same risk in evidence_links. Never link a task to a different risk. If a risk has no evidence, write \"No current signal\".\n3. Copy impact and mitigation text from the register; anything you add goes in \"Next Action [SUGGESTED]\".\n4. Always cite task IDs (e.g. \"T024\"), never vague phrases like \"ongoing tasks\".\n5. No probabilities, money amounts or dates that are not in SOURCE DATA.\n\nVAGUE INPUT RULE: If no risk register and no project description are provided, reply only: \"INSUFFICIENT DETAIL - cannot assess risks without: <missing items>\".\n";
let source;
if (router.project_ref === 'abcde') {
  const byId = Object.fromEntries(Object.values(facts.by_sprint).flatMap(s => s.tasks).map(t => [t.id, t]));
  const raw = Object.fromEntries(project.tasks.map(t => [t.task_id, t]));
  const signalOf = id => {
    if (facts.blocked.find(t => t.id === id)) return { type: 'Blocked', weight: 3, reason: facts.blocked.find(t => t.id === id).reason };
    if (facts.overdue.find(t => t.id === id)) return { type: 'Overdue', weight: 2, reason: facts.overdue.find(t => t.id === id).reason };
    if (facts.at_risk.find(t => t.id === id)) return { type: 'At risk', weight: 1, reason: facts.at_risk.find(t => t.id === id).reason };
    return null;
  };
  // Which task-board work relates to which register risk (keyword rules on task name / label / description)
  const RULES = {
    R01: t => /data/i.test(t.task_name) && !/legal|security|compliance/i.test(t.labels + ' ' + t.task_name),
    R02: t => /integrat|deploy|rollout/i.test(t.task_name),
    R03: t => /training/i.test(t.task_name),
    R04: t => /training|pilot|feedback/i.test(t.task_name),
    R05: t => /compliance|legal/i.test(t.labels + ' ' + t.task_name),
    R08: t => /monitoring|drift|retrain/i.test(t.task_name + ' ' + t.description),
    R09: t => /security/i.test(t.labels + ' ' + t.task_name),
    R10: t => /vendor|platform/i.test(t.task_name),
  };
  const PRIORITY = { High: 3, Medium: 2, Low: 1 };
  const evidence = project.risks.map(r => {
    const tasks = Object.values(raw).filter(t => RULES[r.risk_id] && RULES[r.risk_id](t) && t.status !== 'Done');
    const live = tasks.map(t => ({ id: t.task_id, name: t.task_name, status: t.status, due: t.due_date, priority: t.priority, signal: signalOf(t.task_id) }))
      .filter(x => x.signal);
    const planned = tasks.filter(t => !signalOf(t.task_id)).map(t => `${t.task_id} ${t.task_name} (${t.status}, due ${t.due_date})`);
    const score = live.reduce((a, x) => a + x.signal.weight * 10 + (PRIORITY[x.priority] || 0), 0);
    return {
      risk_id: r.risk_id, category: r.category,
      evidence_strength: live.length ? 'LIVE SIGNAL' : planned.length ? 'PLANNED WORK ONLY' : 'NO CURRENT SIGNAL',
      live_signals: live.map(x => `${x.id} ${x.name} - ${x.signal.reason.startsWith('Blocked') ? x.signal.reason : x.signal.type + ': ' + x.signal.reason}`),
      planned_related_tasks: planned,
      evidence_score: score,
    };
  });
  const STRENGTH = { 'LIVE SIGNAL': 2, 'PLANNED WORK ONLY': 1, 'NO CURRENT SIGNAL': 0 };
  const ranking = [...evidence].sort((a, b) => b.evidence_score - a.evidence_score || STRENGTH[b.evidence_strength] - STRENGTH[a.evidence_strength] || a.risk_id.localeCompare(b.risk_id))
    .map((e, i) => `${i + 1}. ${e.risk_id} (${e.evidence_strength}, score ${e.evidence_score})`);
  source = {
    project: project.name,
    description: project.description,
    report_date: facts.report_date,
    current_phase: facts.current_phase && `${facts.current_phase.phase}. ${facts.current_phase.name} (${facts.current_phase.start_date} to ${facts.current_phase.end_date})`,
    risk_register: project.risks,
    evidence_links: evidence,
    evidence_ranking: ranking,
    ranking_rule: 'Score = sum over linked live signals of (Blocked 30 / Overdue 20 / At risk 10) + task priority (High 3, Medium 2, Low 1). Ties: planned work before no signal, then risk ID.',
  };
} else {
  source = { project: 'User-described project', description: router.user_supplied_details, risk_register: 'Not provided', evidence_links: 'Not provided' };
}
const request = {
  model: ctx.config.specialist_model, temperature: 0.1,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `USER REQUEST: ${ctx.message}\n\nSOURCE DATA:\n${JSON.stringify(source, null, 1)}` },
  ],
};
return [{ json: { ...ctx, agent_name: 'Risk Assessor Agent', request, agent_started_ms: Date.now() } }];

// Status Context — pre-computed counts and task lists for the requested scope (a sprint, or the whole project).
const ctx = $input.first().json;
const { facts, router } = ctx;
const SYSTEM = "ROLE: You are Mira's Status Reporter Agent. You turn pre-computed task-board facts into a clear weekly status report.\n\nINPUT: A FACTS JSON block computed by code from the task board (status counts, the tasks in scope, overdue / blocked / at-risk tasks, upcoming milestones, a rule-based health rating with reasons, and the report date), plus the user's request.\n\nOUTPUT:\n- If the user asks a direct question (e.g. \"how many tasks are done?\"), answer it in the first 1-3 lines using the exact counts, then give a compact summary table.\n- If the user asks for a report, return Markdown:\n  # Weekly Status Report - <scope> - week ending <report date>\n  **Overall health:** <rating from FACTS> - <reasons from FACTS>\n  ## Summary\n  Table of counts (copied exactly from FACTS) for the scope, and for the whole project if provided.\n  ## Completed\n  ## In Progress\n  ## Blocked\n  ## To Do (in scope)\n  Each list: Task ID - task name - assignee - due date.\n  ## Overdue / Carry-over\n  ## Upcoming Milestones (next 14 days)\n  ## Asks & Escalations\n  Only items derived from blocked or overdue tasks.\n\nRULES:\n1. Every number must be copied from FACTS. Never compute or estimate percentages, velocity or effort that FACTS does not contain.\n2. Never mention a task, person, date or milestone that is not in FACTS.\n3. If a section has no items, write \"None\".\n4. Do not change any task's status, even if it looks late.\n\nVAGUE INPUT RULE: If FACTS contains no tasks, reply only: \"NO TASK DATA - cannot report status. Please share a task board export (task, status, assignee, due date, sprint).\"\n";
const allTasks = Object.values(facts.by_sprint).flatMap(s => s.tasks);
const byStatus = list => Object.fromEntries(['Done', 'In Progress', 'Blocked', 'To Do'].map(s => [s, list.filter(t => t.status === s)]));
const sprintKey = router.sprint ? `Sprint ${router.sprint}` : null;
let scopeFacts;
if (sprintKey && facts.by_sprint[sprintKey]) {
  const sp = facts.by_sprint[sprintKey];
  scopeFacts = {
    scope: sprintKey,
    scope_counts: sp.counts,
    scope_tasks_by_status: byStatus(sp.tasks),
    carry_over_from_earlier_sprints: facts.overdue.filter(t => Number(t.sprint.replace(/\D/g, '')) < router.sprint),
    project_counts: facts.status_counts,
  };
} else if (sprintKey) {
  scopeFacts = { scope: sprintKey, scope_counts: { Total: 0 }, scope_tasks_by_status: {}, note: `${sprintKey} does not exist on the task board` };
} else {
  scopeFacts = {
    scope: 'Whole project',
    scope_counts: facts.status_counts,
    percent_done: facts.percent_done,
    scope_tasks_by_status: byStatus(allTasks),
    current_sprint: facts.current_sprint,
  };
}
const FACTS = {
  report_date: facts.report_date,
  project: ctx.project.name,
  ...scopeFacts,
  overdue: facts.overdue, blocked: facts.blocked, at_risk: facts.at_risk,
  upcoming_milestones_next_14_days: facts.upcoming_milestones,
  health: facts.health, health_reasons: facts.health_reasons,
};
const request = {
  model: ctx.config.specialist_model, temperature: 0,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `USER REQUEST: ${ctx.message}\n\nFACTS:\n${JSON.stringify(FACTS, null, 1)}` },
  ],
};
return [{ json: { ...ctx, agent_name: 'Status Reporter Agent', scope_task_ids: sprintKey ? (facts.by_sprint[sprintKey]?.tasks || []).map(t => t.id) : allTasks.map(t => t.id), request, agent_started_ms: Date.now() } }];

// Milestone Context — dated timeline + delivery alerts for the Milestone Tracker (extended capability).
const ctx = $input.first().json;
const { facts } = ctx;
const SYSTEM = "ROLE: You are Mira's Milestone Tracker Agent (Milestone Alert System). You flag what is blocked, overdue or at risk, and which milestones are coming up.\n\nINPUT: A FACTS JSON block computed by code: report date, current phase, phase schedule with dates, upcoming milestones within the alert window, blocked tasks, overdue tasks, at-risk tasks (with the rule that flagged each), alert_counts, plus the user's question.\n\nOUTPUT (Markdown):\n1. A direct answer to the user's question in 1-3 lines, using the exact numbers in alert_counts.\n2. ## Alerts\n   Table: Item | Type (Blocked / Overdue / At Risk / Upcoming Milestone) | Due | Owner | Why (from FACTS) | Suggested Action [SUGGESTED]\n   - For tasks, Item MUST start with the task ID, e.g. \"T024 - Security review of AI infrastructure\".\n   - Include EVERY task in blocked, overdue and at_risk - the number of task rows must equal alert_counts.total_task_alerts. Then add the upcoming milestones.\n3. ## Milestone Outlook\n   Current phase, milestones in the window with due dates, and the next milestone after the window.\n4. ## Method\n   One line stating the report date and the at-risk rules (copied from FACTS).\n\nRULES:\n1. Only milestones from the timeline and only dates from FACTS, written as YYYY-MM-DD. Never calculate new dates.\n2. Only tasks listed in FACTS. Never upgrade or downgrade a task's status, and never drop one.\n3. \"Why\" must quote the FACTS reason (e.g. \"Blocked: waiting for security team availability\").\n4. If the window contains no milestones, say so and name the next one from FACTS.\n\nVAGUE INPUT RULE: If FACTS contains no timeline and no tasks, reply only: \"NO PROJECT DATA - cannot track milestones.\"\n";
const FACTS = {
  report_date: facts.report_date,
  project: ctx.project.name,
  current_phase: facts.current_phase,
  phase_schedule: facts.phases.map(({ phase, name, weeks, start_date, end_date, schedule_status }) => ({ phase, name, weeks, start_date, end_date, schedule_status })),
  alert_window_days: ctx.config.milestone_window_days,
  upcoming_milestones_in_window: facts.upcoming_milestones,
  next_milestones_after_window: facts.next_after_window,
  blocked: facts.blocked, overdue: facts.overdue, at_risk: facts.at_risk,
  at_risk_rules: facts.at_risk_rules,
  alert_counts: { blocked: facts.blocked.length, overdue: facts.overdue.length, at_risk: facts.at_risk.length, total_task_alerts: facts.blocked.length + facts.overdue.length + facts.at_risk.length, upcoming_milestones: facts.upcoming_milestones.length },
  data_notes: facts.data_notes,
};
const request = {
  model: ctx.config.specialist_model, temperature: 0,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `USER REQUEST: ${ctx.message}\n\nFACTS:\n${JSON.stringify(FACTS, null, 1)}` },
  ],
};
return [{ json: { ...ctx, agent_name: 'Milestone Tracker Agent', request, agent_started_ms: Date.now() } }];

// Stakeholder Context — ONLY the requested sprint's tasks are passed, so other sprints cannot leak into the email.
const ctx = $input.first().json;
const { facts, router } = ctx;
const SYSTEM = "ROLE: You are Mira's Stakeholder Update Agent. You write a concise, professional stakeholder email about one sprint.

INPUT: A FACTS JSON block computed by code containing ONLY the requested sprint's tasks (with status, owner, due date), the sprint's counts, the target audience, and the report date.

OUTPUT: A plain-text email:
Subject: <project> - <Sprint N> progress update
Hi all,
<2-sentence summary with the counts from FACTS>
Completed: <bullets: task - owner>
In progress: <bullets: task - owner - due date; mark "past due" only if FACTS says overdue>
Blocked / risks: <only from in-scope tasks; otherwise "None in this sprint">
Next steps: <only the in-scope tasks that are not Done>
Regards,
Mira (Project Intelligence Assistant) on behalf of the PMO

Audience tone: leadership = outcome-focused, no jargon; engineering = task-level detail; client = outcomes and dates only.

RULES:
1. Mention ONLY tasks in FACTS (the requested sprint). Never mention tasks, plans or sprints beyond it.
2. Copy counts, names, owners and dates exactly. No percentages unless FACTS contains them.
3. Do not invent achievements, metrics, decisions or recipients' names.

VAGUE INPUT RULE: If FACTS has no tasks for the sprint, reply only: "NO TASK DATA FOR THIS SPRINT - cannot write the update."
";
const sprintKey = router.sprint ? `Sprint ${router.sprint}` : facts.current_sprint;
const sp = facts.by_sprint[sprintKey] || { counts: { Total: 0 }, tasks: [] };
const FACTS = {
  project: ctx.project.name,
  report_date: facts.report_date,
  sprint: sprintKey,
  audience: router.audience || 'leadership',
  sprint_counts: sp.counts,
  sprint_tasks: sp.tasks.map(t => ({ ...t, overdue: t.status !== 'Done' && t.days_to_due < 0 })),
};
const request = {
  model: ctx.config.specialist_model, temperature: 0.3,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `USER REQUEST: ${ctx.message}

FACTS:
${JSON.stringify(FACTS, null, 1)}` },
  ],
};
return [{ json: { ...ctx, agent_name: 'Stakeholder Update Agent', scope_task_ids: sp.tasks.map(t => t.id), request, agent_started_ms: Date.now() } }];

// Clarifier (rule-based, no LLM) — when data is insufficient Mira asks, it never guesses.
// Deterministic by design: zero hallucination risk and zero token cost on vague inputs.
const ctx = $input.first().json;
const { router } = ctx;
const NEEDS = {
  plan: ['Project goal and scope (what is being built and why)', 'Key deliverables', 'Timeline: start date, duration or deadline', 'Team size and roles', 'Constraints: budget, technology, dependencies', 'Success criteria / KPIs'],
  risk: ['What the project is: domain, scope and goals', 'Timeline and current phase', 'Team, vendors and technologies involved', 'Known constraints (budget, compliance, integrations)', 'Any existing risk register or known issues'],
  status: ['Task board export (CSV, Trello or Jira) with task name, status, assignee, due date and sprint', 'Reporting period (which week or sprint)'],
  milestone: ['Project timeline with milestones and dates', 'Task board export with statuses and due dates'],
  stakeholder_update: ['Task board export for the sprint (task, status, owner, due date)', 'Audience (leadership, engineering or client)'],
};
const LABEL = { plan: 'a project plan', risk: 'a risk assessment', status: 'a status report', milestone: 'a milestone report', stakeholder_update: 'a stakeholder update' };
let answer;
if (router.intent === 'unsupported' || !ctx.message) {
  answer = [
    "I'm Mira, a project intelligence assistant. I can help with:",
    '- Project plans (phases, milestones, timeline)',
    '- Risk assessments and top risks',
    '- Weekly status reports and task counts',
    '- Blocked / at-risk tasks and upcoming milestones',
    '- Stakeholder update emails for a sprint',
    '',
    'Data currently loaded: the ABCDE Ltd. AI Adoption Project (description, timeline, risk register, task board).',
  ].join('\n');
} else {
  const isNoData = ['status', 'milestone', 'stakeholder_update'].includes(router.intent);
  const given = router.user_supplied_details ? `"${router.user_supplied_details}"` : 'no project details';
  answer = [
    isNoData
      ? `NO TASK DATA AVAILABLE - I can't produce ${LABEL[router.intent]} from ${given}. Reporting progress without task data would mean inventing task statuses and percentages.`
      : `INSUFFICIENT DETAIL - I can't generate ${LABEL[router.intent]} from ${given} without inventing scope, dates and people.`,
    '',
    'Please share:',
    ...NEEDS[router.intent].map(n => `- ${n}`),
    ...(router.guardrails.some(g => g.startsWith('Sprint')) ? ['', `Note: ${router.guardrails.join('; ')}.`] : []),
    '',
    'Or ask about the ABCDE Ltd. AI Adoption Project, which is already loaded.',
  ].join('\n');
}
return [{ json: { ...ctx, agent_name: 'Clarifier (rule-based)', rule_based_answer: answer, agent_started_ms: Date.now() } }];

// Grounding Check — automatic post-generation evaluator. Every task ID, risk ID and date in the answer must exist
// in the source data; stakeholder emails may only mention in-scope sprint tasks. Flags are returned with the answer
// and sent to Langfuse, so hallucinations show up in traces and metrics.
const ctx = $input.first().json;
const { facts, router, config: cfg } = ctx;
const answer = ctx.answer || '';
const uniq = a => [...new Set(a)];
const flags = [];

const taskIds = uniq(answer.match(/\bT0\d{2}\b/g) || []);
const riskIds = uniq(answer.match(/\bR\d{2}\b/g) || []);
const dates = uniq(answer.match(/\b20\d{2}-\d{2}-\d{2}\b/g) || []);

taskIds.filter(id => !facts.all_task_ids.includes(id)).forEach(id => flags.push(`Unknown task ID ${id}`));
riskIds.filter(id => !facts.all_risk_ids.includes(id)).forEach(id => flags.push(`Unknown risk ID ${id}`));

const knownDates = new Set([
  facts.report_date, facts.project_start, facts.project_end,
  ...Object.values(facts.by_sprint).flatMap(s => s.tasks.map(t => t.due)),
  ...facts.phases.flatMap(p => [p.start_date, p.end_date]),
]);
if (router.project_ref === 'abcde') dates.filter(d => !knownDates.has(d)).forEach(d => flags.push(`Date ${d} not found in source data`));

if (router.route === 'stakeholder_update' && ctx.scope_task_ids) {
  taskIds.filter(id => !ctx.scope_task_ids.includes(id)).forEach(id => flags.push(`Out-of-scope task ${id} mentioned in sprint update`));
}
if (router.route === 'status' && router.sprint && ctx.scope_task_ids) {
  const allowed = new Set([...ctx.scope_task_ids, ...facts.overdue.map(t => t.id), ...facts.blocked.map(t => t.id), ...facts.at_risk.map(t => t.id)]);
  taskIds.filter(id => !allowed.has(id)).forEach(id => flags.push(`Task ${id} is outside the requested scope`));
}
// v2 completeness checks (after baseline run 1, where T8 silently dropped an at-risk task):
// every alert task must be mentioned (by ID or name) in milestone answers; every in-scope task in sprint reports/emails.
const allTaskList = Object.values(facts.by_sprint).flatMap(s => s.tasks);
const mentioned = id => { const t = allTaskList.find(x => x.id === id); return answer.includes(id) || (t && answer.toLowerCase().includes(t.name.toLowerCase())); };
if (router.route === 'milestone') {
  [...facts.blocked, ...facts.overdue, ...facts.at_risk].map(t => t.id).filter(id => !mentioned(id)).forEach(id => flags.push(`Omitted alert task ${id}`));
}
if ((router.route === 'stakeholder_update' || (router.route === 'status' && router.sprint)) && ctx.scope_task_ids) {
  ctx.scope_task_ids.filter(id => !mentioned(id)).forEach(id => flags.push(`Omitted in-scope task ${id}`));
}
const notes = [];
if (router.route !== 'clarify' && router.project_ref !== 'abcde') notes.push('Answer is based only on user-supplied details (no project files loaded) - review before sharing');

// Cost per call (USD) from the price table in Config
const price = m => cfg.prices[Object.keys(cfg.prices).find(k => (m || '').startsWith(k))] || { input: 0, output: 0 };
const agents = ctx.calls.map(c => ({
  agent: c.agent, model: c.model, input_tokens: c.input_tokens, output_tokens: c.output_tokens, latency_ms: c.latency_ms,
  cost_usd: Number(((c.input_tokens * price(c.model).input + c.output_tokens * price(c.model).output) / 1e6).toFixed(6)),
}));
const totals = agents.reduce((a, c) => ({
  input_tokens: a.input_tokens + c.input_tokens, output_tokens: a.output_tokens + c.output_tokens,
  cost_usd: Number((a.cost_usd + c.cost_usd).toFixed(6)),
}), { input_tokens: 0, output_tokens: 0, cost_usd: 0 });
totals.latency_ms = Date.now() - ctx.started_ms;

const grounding = { passed: flags.length === 0, flags, notes, task_ids_cited: taskIds, risk_ids_cited: riskIds };
const response = {
  test_id: ctx.test_id, request: ctx.message, as_of_date: facts.report_date,
  route: router.route, intent: router.intent, project_ref: router.project_ref, sprint: router.sprint,
  router_reason: router.reason, guardrails: router.guardrails,
  answer, grounding, agents, totals, trace_id: ctx.trace_id,
};

// Langfuse via OpenTelemetry (OTLP/HTTP JSON) - one trace per request:
//   root "mira-request" (agent) -> Compute Facts (span) -> Orchestrator (generation) -> specialist (generation, or span
//   for the rule-based Clarifier) -> Grounding Check (guardrail). The grounded score goes to the Scores API separately.
// (v3: moved off the legacy /api/public/ingestion endpoint, which Langfuse Cloud retires on 16 Nov 2026.)
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const traceId = hex(32), rootId = hex(16);
const ns = iso => `${Date.parse(iso)}000000`;
const str = v => (typeof v === 'string' ? v : JSON.stringify(v));
const attr = (key, v) => (Array.isArray(v) && v.every(x => typeof x === 'string') ? { key, value: { arrayValue: { values: v.map(x => ({ stringValue: String(x) })) } } }
  : typeof v === 'number' ? { key, value: { intValue: Math.round(v) } } : { key, value: { stringValue: str(v) } });
const span = (name, parent, start, end, type, attrs) => ({
  traceId, spanId: parent === null ? rootId : hex(16), ...(parent ? { parentSpanId: parent } : {}), name, kind: 1,
  startTimeUnixNano: ns(start), endTimeUnixNano: ns(end),
  attributes: [attr('langfuse.observation.type', type), ...attrs], status: {},
});
const endIso = new Date().toISOString();
const tags = ['mira', `route:${router.route}`, grounding.passed ? 'grounded' : 'grounding-flags'];
const spans = [
  span('mira-request', null, ctx.started_at, endIso, 'agent', [
    attr('langfuse.trace.name', 'mira-request'), attr('langfuse.trace.tags', tags),
    ...(ctx.session_id ? [attr('langfuse.session.id', ctx.session_id)] : []),
    attr('langfuse.observation.input', ctx.message), attr('langfuse.observation.output', answer),
    attr('langfuse.trace.metadata.test_id', ctx.test_id || ''), attr('langfuse.trace.metadata.route', router.route),
    attr('langfuse.trace.metadata.grounded', String(grounding.passed)), attr('langfuse.trace.metadata.cost_usd', String(totals.cost_usd)),
    attr('langfuse.trace.metadata.as_of_date', facts.report_date),
  ]),
  span('Compute Facts (code)', rootId, ctx.started_at, new Date(Date.parse(ctx.started_at) + (ctx.facts_ms || 1)).toISOString(), 'span', [
    attr('langfuse.observation.output', { status_counts: facts.status_counts, health: facts.health, blocked: facts.blocked.map(t => t.id), overdue: facts.overdue.map(t => t.id) }),
  ]),
  ...ctx.calls.map((c, i) => c.model.startsWith('none')
    ? span(c.agent, rootId, c.start_time, c.end_time, 'guardrail', [attr('langfuse.observation.input', c.input), attr('langfuse.observation.output', c.output)])
    : span(c.agent, rootId, c.start_time, c.end_time, 'generation', [
      attr('langfuse.observation.model.name', c.model), attr('langfuse.observation.input', c.input), attr('langfuse.observation.output', c.output),
      attr('langfuse.observation.usage_details', { input: c.input_tokens, output: c.output_tokens, total: c.input_tokens + c.output_tokens }),
      attr('langfuse.observation.cost_details', { total: agents[i].cost_usd }),
    ])),
  span('Grounding Check (code)', rootId, endIso, new Date(Date.parse(endIso) + 1).toISOString(), 'evaluator', [
    attr('langfuse.observation.output', grounding), attr('langfuse.observation.level', grounding.passed ? 'DEFAULT' : 'WARNING'),
  ]),
];
const otel = { resourceSpans: [{ resource: { attributes: [attr('service.name', 'mira-n8n')] }, scopeSpans: [{ scope: { name: 'mira' }, spans }] }] };
const score = { traceId, name: 'grounded', value: grounding.passed ? 1 : 0, dataType: 'NUMERIC', comment: flags.join('; ') || 'all cited IDs and dates found in source data' };
response.langfuse_trace_id = traceId;

return [{ json: { response, langfuse_enabled: !!cfg.langfuse_enabled, langfuse_url: `${cfg.langfuse_host}/api/public/otel/v1/traces`, langfuse_body: otel, langfuse_score_url: `${cfg.langfuse_host}/api/public/scores`, langfuse_score_body: score } }];
